/**
* Unescapes any Java literals found in the input string. For example, it will turn a sequence of '\' and 'n' into a newline character, unless the '\' is preceded by another '\'.
* @param str the input string, may be null
* @return the unescaped string, null if null string input
* @throws Exception if an unescaping error occurs
*/
public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder sb = new StringBuilder(str);
    int len = sb.length();
    for (int i = 0; i < len; i++) {
        char c = sb.charAt(i);
        if (c == '\\') {
            if (i == len - 1) {
                throw new Exception("Unterminated escape sequence at end of string");
            }
            c = sb.charAt(i + 1);
            switch (c) {
                case 'n':
                    sb.setCharAt(i++, '\n');
                    break;
                case 'b':
                    sb.setCharAt(i++, '\b');
                    break;
                case 't':
                    sb.setCharAt(i++, '\t');
                    break;
                case 'f':
                    sb.setCharAt(i++, '\f');
                    break;
                case 'r':
                    sb.setCharAt(i++, '\r');
                    break;
                case '\'':
                    sb.setCharAt(i++, '\'');
                    break;
                case '\"':
                    sb.setCharAt(i++, '\"');
                    break;
                case '\uffff':
                    //ill-formed escape sequence
                    throw new Exception("Illegal escape character at index " + (i - 1));
            }
        }
    }
    return sb.toString();
}

