    Rectangle rect = table.getCellRect(row, 0, true);

    if(rect.y + height > viewport.getViewPosition().y + viewport.getHeight()){
        // Cell is not visible in the viewport; scroll upward
        int newY = rect.y - (height - (viewport.getViewPosition().y + viewport.getHeight() - rect.y));
        viewport.setViewPosition(new Point(viewport.getViewPosition().x, newY)); 
    }

    // Wait long enough for the table to repaint the selected row
    if(comp instanceof JComponent){
        try{
